    Q_OBJECT
    Q_PROPERTY(bool classical READ isClassical WRITE setClassical NOTIFY classicalChanged)
public:
    bool isClassical() const { return m_classical; }
    void setClassical(bool v) { if (v != m_classical) { m_classical = v; emit classicalChanged(); } }
    bool composerEnabled() const { return isClassical(); }   // decision
    Q_INVOKABLE void apply();                                // command
signals:
    void classicalChanged();
private:
    bool m_classical = false;
};
