QProperty<bool> classical;
QProperty<bool> composerEnabled;
composerEnabled.setBinding([&] { return classical.value(); });  // decision as a binding
// keep getters/setters trivial; dependencies must be bindable properties

class AlbumPm {
public:
    void on_change(std::function<void()> f) { subs_.push_back(std::move(f)); }
    bool composer_enabled() const { return classical_; }   // decision
    void set_classical(bool v) { classical_ = v; notify(); }
private:
    void notify() { for (auto &f : subs_) f(); }
    std::vector<std::function<void()>> subs_;
    bool classical_ = false;
};
